import java.util.*;

class Solution {
    public List<List<Integer>> coinCombos(int[] coins, int target) {
        Arrays.sort(coins);                         // lets us stop early
        List<List<Integer>> out = new ArrayList<>();
        go(coins, 0, target, new ArrayList<Integer>(), out);
        return out;
    }

    private void go(int[] coins, int i, int left, List<Integer> cur, List<List<Integer>> out) {
        if (left == 0) { out.add(new ArrayList<>(cur)); return; }
        for (int j = i; j < coins.length; j++) {
            if (coins[j] > left) break;             // all later coins are bigger too
            cur.add(coins[j]);
            go(coins, j, left - coins[j], cur, out); // stay at j: coin can be reused
            cur.remove(cur.size() - 1);
        }
    }
}

