function coinCombos(coins, target) {
  // dp over targets: ways[t] = list of combos (non-decreasing by coin index)
  const c = coins.slice().sort((a, b) => a - b);
  let ways = Array.from({ length: target + 1 }, () => []); ways[0] = [[]];
  for (const coin of c) for (let t = coin; t <= target; t++) for (const w of ways[t - coin]) ways[t].push([...w, coin]);
  return ways[target];
}
